'use strict';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M15 13h6M16 16h1"/>',check:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="m8 12 3 3 5-6M8 3v3h8V3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M8 14h2M14 14h2M8 18h2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2L12 3Z M12 9v5M12 17h.01"/>',file:'<path d="M14 2H4v20h16V8l-6-6ZM14 2v6h6M8 13h8M8 17h6"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="m12 7 5 4-2 6H9l-2-6 5-4ZM12 7V3M17 11l4-2M15 17l3 3M9 17l-3 3M7 11 3 9"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n);
const names=['Mateo Rojas','Samuel Torres','Valentina Duarte','Nicolás Peña','Emiliano Castro','Martina López','Sebastián Ruiz','Gabriel Mora','Daniel Suárez','Isabella León','Tomás Acosta','Santiago Rueda'];
let players=names.map((name,i)=>({id:i+1,name,category:i<8?'2016–2017':'2012–2013',balance:[0,50000,0,25000,0,50000,0,0,50000,0,0,50000][i],guardian:['Laura Rojas','Andrés Torres','Camila Duarte','Sandra Peña'][i%4],dob:i<8?'2016-07-12':'2012-04-20',weight:i<8?32:45,height:i<8?138:156,permit:i===5,modality:'Mensual',phone:'300 000 0000',email:'acudiente'+(i+1)+'@example.com'}));
let payments=players.filter(p=>p.balance<50000).map((p,i)=>({id:101+i,playerId:p.id,name:p.name,amount:50000-p.balance,method:i%2?'Efectivo':'Transferencia',concept:'Mensualidad · Septiembre 2026',date:'2026-09-'+String(3+i).padStart(2,'0')}));
let selectedCoach='felipe';let attendance={},attendanceSaved=false,view='inicio',role='admin',query='',filter='Todas',planName='',executed=false;
const main=document.querySelector('#main');const modal=document.querySelector('#modal');
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const eligible=p=>p.balance===0||p.permit;
const badge=p=>p.permit&&p.balance>0?'<span class="badge warn">Permiso temporal</span>':p.balance>0?'<span class="badge danger">Restringido</span>':'<span class="badge ok">Habilitado</span>';
const person=p=>`<div class="person"><span class="avatar">${esc(initials(p.name))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small></div></div>`;
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3800)}
function go(v){view=v;query='';filter='Todas';render();document.querySelector('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function title(k,t,s,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p class="sub">${s}</p></div><div class="actions">${buttons}</div></div>`}
function btn(text,action,primary=false,ic=''){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${ic?icon(ic):''}${text}</button>`}
function stat(label,value,note,ic){return `<article class="stat"><div class="stat-top">${label}${icon(ic)}</div><strong>${value}</strong><small>${note}</small></article>`}
function render(){const navs=role==='admin'?[['inicio','Resumen','home'],['deportistas','Deportistas','users'],['pagos','Pagos y cartera','wallet'],['asistencia','Asistencia','check'],['sesiones','Entrenamientos','calendar'],['equipo','Equipo y categorías','users'],['honorarios','Pago a entrenadores','wallet']]:[['inicio','Mi jornada','home'],['asistencia','Asistencia','check'],['deportistas','Mis deportistas','users'],['sesiones','Entrenamientos','calendar']];document.querySelector('#nav').innerHTML=navs.map(([v,t,i])=>`<button class="${v===view?'active':''}" onclick="go('${v}')">${icon(i)}${t}</button>`).join('');document.querySelector('#crumb').textContent=navs.find(n=>n[0]===view)?.[1]||'Resumen';document.querySelector('#role-label').textContent=role==='admin'?'Administración':'Entrenador · '+coachById(selectedCoach).name;main.innerHTML=({inicio:dashboard,deportistas:roster,pagos:paymentsView,asistencia:attendanceView,sesiones:sessionsView,equipo:teamView,honorarios:coachPaymentsView}[view]||dashboard)();}
function dashboard(){if(role==='coach')return coachHome();const received=payments.reduce((a,p)=>a+p.amount,0),pending=players.reduce((a,p)=>a+p.balance,0);return title('PANEL ADMINISTRATIVO','El club, en un solo lugar.','Martes, 29 de septiembre de 2026',btn('Registrar pago','paymentForm()',true,'plus'))+`<div class="stats">${stat('Deportistas de prueba',players.length,'2 categorías en esta muestra','users')}${stat('Recaudo de septiembre',money(received),'Mensualidades confirmadas de la muestra','wallet')}${stat('Cartera pendiente',money(pending),players.filter(p=>p.balance>0).length+' deportistas con saldo','clock')}${stat('Habilitados',players.filter(eligible).length+' / '+players.length,'Incluye permisos temporales','check')}</div><div class="dashboard-grid"><div><section class="card"><div class="card-head"><div><h2>Así se mueve el club</h2><p>Ejemplo de visualización · abril a septiembre</p></div><span class="badge blue">2026</span></div><div class="chart"><div class="legend"><span><i></i>Ingresos</span><span><i class="light"></i>Gastos</span><span>Escala ilustrativa</span></div><div class="bars">${[55,75,61,88,72,96].map((h,i)=>`<div class="bar-col"><div class="bar" style="height:${h}%" title="Ingresos ilustrativos"></div><div class="bar expense" style="height:${h*.57}%" title="Gastos ilustrativos"></div></div>`).join('')}</div><div class="chart-labels">${['Abr','May','Jun','Jul','Ago','Sep'].map(m=>'<span>'+m+'</span>').join('')}</div></div></section><section class="card"><div class="card-head"><h2>Últimos pagos</h2><button class="btn link" onclick="go('pagos')">Ver todos</button></div>${paymentTable(payments.slice(-4).reverse(),false)}</section></div><div>${trainingCard()}<section class="card"><div class="card-head"><h2>Para tener en cuenta</h2></div><div class="info-row">${icon('alert')}<div><strong>Mensualidades pendientes</strong><small>Revisar saldos y acuerdos</small></div><span class="count">${players.filter(p=>p.balance>0).length}</span></div><div class="info-row">${icon('file')}<div><strong>Planeación de hoy</strong><small>${planName?'Archivo adjunto en esta prueba':'Pendiente de adjuntar'}</small></div><button class="btn link" onclick="go('sesiones')">Ver</button></div><div class="info-row">${icon('check')}<div><strong>Asistencia de hoy</strong><small>${attendanceSaved?'Guardada en esta prueba':'Lista por completar'}</small></div><button class="btn link" onclick="go('asistencia')">Abrir</button></div></section></div></div>`;}
function trainingCard(){return `<section class="card training"><div class="card-head"><div><h2>Hoy en la cancha</h2><p>Martes · 29 de septiembre</p></div>${icon('ball')}</div><div class="training-inner"><span class="tag">17:30 – 19:00</span><h3>Categoría 2016–2017</h3><p>Cancha sintética · 8 deportistas<br>Conducción y pase en movimiento</p><button class="btn" onclick="go('asistencia')">${icon('check')}Tomar asistencia</button></div></section>`;}
function coachHome(){const ps=players.filter(p=>p.category==='2016–2017');return title('MI JORNADA','Nos vemos en la cancha.','Tu categoría, tu planeación y tu lista, a un toque.')+`<div class="stats">${stat('Mis deportistas',ps.length,'Categoría 2016–2017','users')}${stat('Habilitados',ps.filter(eligible).length,'Incluye permisos temporales','check')}${stat('Sesiones de hoy','1','19:00 · Cancha de tierra Beraka','calendar')}${stat('Asistencia',attendanceSaved?'Guardada':'Pendiente','Entrenamiento de hoy','clock')}</div><div class="dashboard-grid"><div>${trainingCard()}</div><div><section class="card"><div class="card-head"><h2>Antes de comenzar</h2></div><div class="info-row">${icon('file')}<div><strong>Planeación</strong><small>${planName?'Archivo adjunto':'Adjunta tu foto o PDF'}</small></div><button class="btn link" onclick="go('sesiones')">Abrir</button></div><div class="info-row">${icon('users')}<div><strong>Contactos de emergencia</strong><small>Disponibles en cada ficha</small></div><button class="btn link" onclick="go('deportistas')">Consultar</button></div></section></div></div>`;}
function roster(){return title('DEPORTISTAS',role==='admin'?'Un equipo que conocemos.':'Mi equipo.','Consulta la ficha, el acudiente y la habilitación de cada deportista.',role==='admin'?btn('Inscribir deportista','enrollForm()',true,'plus'):'')+`<div class="toolbar"><label class="search">${icon('search')}<input aria-label="Buscar deportista" placeholder="Buscar por nombre…" oninput="query=this.value;updateRoster()"></label>${role==='admin'?'<select class="filter" aria-label="Filtrar categoría" onchange="filter=this.value;updateRoster()"><option>Todas</option>'+CLUB.categories.map(c=>'<option>'+c+'</option>').join('')+'</select>':''}<button class="btn" onclick="exportPlayers()">${icon('download')}Exportar lista</button></div><section class="card"><div id="roster-table">${rosterTable()}</div></section>`}
function visiblePlayers(){return players.filter(p=>(role==='admin'||coachCategories(selectedCoach).includes(p.category))&&(filter==='Todas'||p.category===filter)&&p.name.toLowerCase().includes(query.toLowerCase()))}
function rosterTable(){const ps=visiblePlayers();return `<div class="table-wrap"><table><thead><tr><th>Deportista</th><th>Modalidad</th><th>Habilitación</th>${role==='admin'?'<th>Saldo mensualidad</th>':''}<th>Ficha</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${person(p)}</td><td>${esc(p.modality)}</td><td>${badge(p)}</td>${role==='admin'?`<td>${money(p.balance)}</td>`:''}<td><button class="btn link" onclick="profile(${p.id})">Ver ficha</button></td></tr>`).join('')}</tbody></table>${ps.length?'':'<div class="empty">No hay deportistas con ese nombre o categoría.</div>'}</div>`}
function updateRoster(){document.querySelector('#roster-table').innerHTML=rosterTable()}
function paymentsView(){const pending=players.reduce((s,p)=>s+p.balance,0);return title('ADMINISTRACIÓN','Pagos claros. Cuentas al día.','Septiembre de 2026 · Muestra de mensualidades',btn('Registrar pago','paymentForm()',true,'plus'))+`<div class="stats">${stat('Recaudo',money(payments.reduce((s,p)=>s+p.amount,0)),'Pagos confirmados de prueba','wallet')}${stat('Saldo pendiente',money(pending),'Solo mensualidades','clock')}${stat('Con saldo',players.filter(p=>p.balance>0).length,'Deportistas de la muestra','users')}${stat('Restricción',players.filter(p=>!eligible(p)).length,'Regla del día 16 aplicada','alert')}</div><section class="card"><div class="card-head"><div><h2>Cartera de septiembre</h2><p>Un abono reduce el saldo; el permiso temporal se gestiona por separado.</p></div></div><div class="table-wrap"><table><thead><tr><th>Deportista</th><th>Saldo</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${players.filter(p=>p.balance>0).map(p=>`<tr><td>${person(p)}</td><td><b>${money(p.balance)}</b></td><td>${badge(p)}</td><td><button class="btn link" onclick="paymentForm(${p.id})">Registrar abono</button></td></tr>`).join('')||'<tr><td colspan="4">Todas las mensualidades de la muestra están al día.</td></tr>'}</tbody></table></div></section><section class="card"><div class="card-head"><h2>Movimientos confirmados</h2><span class="badge">${payments.length} pagos</span></div>${paymentTable([...payments].reverse(),true)}</section>`}
function paymentTable(ps,full){return `<div class="table-wrap"><table><thead><tr><th>Deportista</th>${full?'<th>Fecha</th>':''}<th>Medio</th><th>Valor</th>${full?'<th>Comprobante</th>':''}</tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><span class="muted">${esc(p.concept)}</span></td>${full?`<td>${p.date.split('-').reverse().join('/')}</td>`:''}<td><span class="badge ${p.method==='Transferencia'?'blue':''}">${p.method}</span></td><td class="recent-amount">${money(p.amount)}</td>${full?`<td><button class="btn link" onclick="receipt(${p.id})">GH-${p.id}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function attendanceView(){const ps=players.filter(p=>p.category==='2016–2017'),marked=ps.filter(p=>attendance[p.id]).length;return title('ENTRENAMIENTO DE HOY','Tomar asistencia','2016–2017 · Martes 29 de septiembre · 17:30 – 19:00',btn('Ver planeación',"go('sesiones')",false,'file'))+`<div class="notice">Hay ${ps.filter(p=>!eligible(p)).length} deportistas restringidos por mensualidad. Su asistencia real puede registrarse; hacerlo no autoriza su participación ni confirma un pago.</div><section class="card"><div class="card-head"><div><h2>Lista de deportistas</h2><p>Cancha sintética · ${ps.length} convocados al entrenamiento</p></div><span class="badge blue" id="att-count">${marked} / ${ps.length}</span></div>${ps.map(p=>`<div class="attendance-row">${person(p)}${badge(p)}<select aria-label="Asistencia de ${esc(p.name)}" onchange="markAttendance(${p.id},this.value)">${[['','Sin registrar'],['presente','Presente'],['ausente','Ausente'],['excusado','Excusado'],['tarde','Llegó tarde']].map(([val,t])=>`<option value="${val}" ${attendance[p.id]===val?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}<div class="attendance-footer"><span id="att-note">${attendanceSaved?'Lista guardada en esta prueba.':'Marca cada deportista antes de guardar.'}</span><button class="btn primary" onclick="saveAttendance()">${icon('check')}Guardar asistencia</button></div></section>`}
function markAttendance(id,val){if(!['','presente','ausente','excusado','tarde'].includes(val))throw Error('Estado inválido');attendance[id]=val;attendanceSaved=false;document.querySelector('#att-count').textContent=Object.values(attendance).filter(Boolean).length+' / '+players.filter(p=>p.category==='2016–2017').length;document.querySelector('#att-note').textContent='Cambios sin guardar.'}
function saveAttendance(){const ps=players.filter(p=>p.category==='2016–2017');if(ps.some(p=>!attendance[p.id]))return toast('Completa el estado de los '+ps.length+' deportistas.');attendanceSaved=true;document.querySelector('#att-note').textContent='Guardada en esta prueba · '+new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});toast('Asistencia guardada en el prototipo.');}
function sessionsView(){return title('TRABAJO DEPORTIVO','Cada sesión cuenta.','Planeación y ejecución del entrenamiento de demostración.')+`<section class="card"><div class="session-card"><div class="datebox"><span>SEP</span><strong>29</strong></div><div class="session-content"><span class="badge ${executed?'ok':'blue'}">${executed?'Realizada':'Programada'}</span><h3 style="margin-top:9px">Conducción y pase en movimiento</h3><p>2016–2017 · 17:30 – 19:00 · Cancha sintética</p></div><div class="session-actions">${btn('Tomar lista',"go('asistencia')",true,'check')}</div></div></section><div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Planeación de la sesión</h2>${icon('file')}</div><div class="training-inner"><p class="sub">Objetivo: mejorar la conducción orientada y el pase con el interior del pie mediante juegos por parejas.</p><div class="section-title">ARCHIVO DE PLANEACIÓN</div><label class="field">Foto o PDF<input type="file" accept="image/*,application/pdf" onchange="attachPlan(this.files[0])"></label><p class="saved-note" id="file-note">${esc(planName?planName+' · adjunto solo en esta prueba':'No hay archivo adjunto.')}</p><p class="muted" style="margin-top:12px">En este prototipo el archivo no se envía ni se conserva al recargar.</p></div></section><section class="card"><div class="card-head"><h2>Ejecución</h2>${icon('ball')}</div><div class="training-inner"><label class="field">Observaciones<textarea id="session-notes" rows="4" placeholder="¿Qué se trabajó? ¿Hubo alguna novedad?">${esc(window.sessionNotes||'')}</textarea></label><div class="form-actions"><button class="btn primary" onclick="completeSession()">Guardar como realizada</button></div></div></section></div>`}
function attachPlan(file){if(!file)return;if(!(file.type.startsWith('image/')||file.type==='application/pdf'))return toast('Selecciona una imagen o PDF.');if(file.size>10*1024*1024)return toast('El archivo debe pesar menos de 10 MB.');planName=file.name;document.querySelector('#file-note').textContent=planName+' · seleccionado a las '+new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});toast('Archivo seleccionado para la demostración.');}
function completeSession(){window.sessionNotes=document.querySelector('#session-notes').value;executed=true;render();toast('Sesión marcada como realizada en esta prueba.');}
function showModal(title,body){document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" onclick="modal.close()" aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal()}
function profile(id){const p=players.find(p=>p.id===id);if(!p)return;showModal('Ficha del deportista',`<div class="profile-head"><span class="avatar">${esc(initials(p.name))}</span><div><h2>${esc(p.name)}</h2><p class="sub">Categoría ${esc(p.category)} · ${esc(p.modality)}</p></div></div>${badge(p)}<div class="section-title">DATOS DEL DEPORTISTA</div><div class="detail-grid"><div class="detail"><small>Fecha de nacimiento</small>${esc(p.dob.split('-').reverse().join('/'))}</div><div class="detail"><small>Inscripción</small>Ficha de demostración</div></div><div class="section-title">ACUDIENTE PRINCIPAL</div><div class="detail-grid"><div class="detail"><small>Nombre</small>${esc(p.guardian)}</div><div class="detail"><small>Celular de ejemplo</small>${esc(p.phone)}</div>${role==='admin'?`<div class="detail full-width"><small>Correo de ejemplo</small>${esc(p.email)}</div>`:''}</div><div class="section-title">CONTACTO DE EMERGENCIA</div><div class="detail-grid"><div class="detail"><small>Contacto adicional · tía</small>Adriana Pérez · ejemplo</div><div class="detail"><small>Celular de ejemplo</small>310 000 0000</div></div><div class="section-title">SEGUIMIENTO FÍSICO</div><div class="form-grid"><label class="field">Peso (kg)<input id="weight" type="number" min="1" max="300" step="0.1" value="${p.weight}" oninput="calcBMI()"></label><label class="field">Estatura (cm)<input id="height" type="number" min="40" max="250" step="0.1" value="${p.height}" oninput="calcBMI()"></label></div><div class="bmi-result"><div>IMC calculado<small class="muted" style="display:block">kg/m² · sin clasificación clínica</small></div><strong id="bmi">${(p.weight/(p.height/100)**2).toFixed(2)}</strong></div><p class="muted" style="margin-top:10px">En niños, la interpretación depende de la edad y el sexo. Esta pantalla solo demuestra el cálculo y no determina la habilitación.</p><div class="form-actions"><button class="btn" onclick="modal.close()">Cerrar</button><button class="btn primary" onclick="saveMeasures(${p.id})">Guardar medición de prueba</button></div>`);}
function calcBMI(){const w=Number(document.querySelector('#weight').value),h=Number(document.querySelector('#height').value);document.querySelector('#bmi').textContent=w>0&&h>=40?(w/(h/100)**2).toFixed(2):'—';}
function saveMeasures(id){const w=document.querySelector('#weight'),h=document.querySelector('#height');if(!w.reportValidity()||!h.reportValidity()||!w.value||!h.value)return toast('Ingresa peso y estatura válidos.');const p=players.find(p=>p.id===id);p.weight=Number(w.value);p.height=Number(h.value);modal.close();toast('Medición actualizada solo en esta prueba.');}
function paymentForm(id){if(role!=='admin')return;const pending=players.filter(p=>p.balance>0);if(!pending.length)return toast('No hay mensualidades pendientes en esta muestra.');showModal('Registrar pago',`<p class="sub" style="margin-bottom:22px">Mensualidad de septiembre de 2026 · operación de prueba</p><form id="payment-form"><div class="form-grid"><label class="field full">Deportista<select id="pay-player" onchange="updatePayAmount()">${pending.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)} · saldo ${money(p.balance)}</option>`).join('')}</select></label><label class="field">Valor recibido (COP)<input id="pay-amount" type="number" min="1" step="1" required></label><label class="field">Medio de pago<select id="pay-method"><option>Efectivo</option><option>Transferencia</option></select></label><label class="field full">Concepto<input value="Mensualidad · Septiembre 2026" readonly></label><label class="field full" style="font-weight:400;display:flex;flex-direction:row;align-items:flex-start"><input type="checkbox" required style="width:18px;margin-top:4px">Confirmo que el pago de ejemplo fue recibido o verificado.</label></div><p class="muted" style="margin-top:15px">El comprobante será de demostración. No se enviará al acudiente.</p><div class="form-actions"><button type="button" class="btn" onclick="modal.close()">Cancelar</button><button class="btn primary" type="submit">Confirmar pago de prueba</button></div></form>`);updatePayAmount();document.querySelector('#payment-form').onsubmit=e=>{e.preventDefault();const p=players.find(p=>p.id===Number(document.querySelector('#pay-player').value)),amount=Number(document.querySelector('#pay-amount').value);if(!p||!Number.isInteger(amount)||amount<=0||amount>p.balance)return toast('El valor debe ser mayor que cero y no superar el saldo.');const item={id:Math.max(...payments.map(p=>p.id),100)+1,playerId:p.id,name:p.name,amount,method:document.querySelector('#pay-method').value,concept:'Mensualidad · Septiembre 2026',date:'2026-09-29'};p.balance-=amount;payments.push(item);render();receipt(item.id);toast('Pago de prueba confirmado. Saldo actualizado.');}}
function updatePayAmount(){const p=players.find(p=>p.id===Number(document.querySelector('#pay-player').value));const input=document.querySelector('#pay-amount');input.value=p.balance;input.max=p.balance;}
function receipt(id){const p=payments.find(p=>p.id===id);if(!p)return;showModal('Comprobante de demostración',`<div class="receipt"><div class="profile-head"><img src="escudo.jpeg" alt="Escudo del club" width="43"><div><h3>García Herreros FC</h3><p class="muted">GH-${p.id} · SIN VALIDEZ COMO RECIBO REAL</p></div></div><div class="receipt-row"><span>Deportista</span><b>${esc(p.name)}</b></div><div class="receipt-row"><span>Concepto</span><span>${esc(p.concept)}</span></div><div class="receipt-row"><span>Medio</span><span>${p.method}</span></div><div class="receipt-row"><span>Fecha</span><span>${p.date.split('-').reverse().join('/')}</span></div><div class="receipt-row" style="border-top:1px solid var(--line);margin-top:10px;padding-top:18px"><span>Valor recibido</span><strong class="total">${money(p.amount)}</strong></div></div><p class="muted">Consulta visual del comprobante. El envío automático por correo se conectará en la versión operativa.</p><div class="form-actions"><button class="btn primary" onclick="modal.close()">Listo</button></div>`)}
function enrollForm(){if(role!=='admin')return;showModal('Inscripción de prueba',`<p class="sub" style="margin-bottom:20px">Registro básico para revisar el formulario. Usa únicamente datos ficticios.</p><form id="enroll-form"><div class="form-grid"><label class="field full">Nombre completo del deportista<input name="name" required maxlength="80" placeholder="Nombre de ejemplo"></label><label class="field">Fecha de nacimiento<input name="dob" type="date" min="2006-01-01" max="2026-09-29" required></label><label class="field">Categoría<select name="category">${CLUB.categories.map(c=>'<option>'+c+'</option>').join('')}</select></label><label class="field full">Nombre del acudiente<input name="guardian" required maxlength="80"></label><label class="field">Celular del acudiente<input name="phone" type="tel" required pattern="[0-9 +()-]{7,20}" placeholder="300 000 0000"></label><label class="field">Correo del acudiente<input name="email" type="email" required placeholder="ejemplo@example.com"></label></div><div class="notice" style="margin-top:20px;margin-bottom:0">La ficha de prueba quedará en modalidad mensual, con $50.000 pendientes. El formulario completo de inscripción y los cobros anuales se implementarán en la versión operativa.</div><div class="form-actions"><button type="button" class="btn" onclick="modal.close()">Cancelar</button><button class="btn primary">Crear ficha de prueba</button></div></form>`);document.querySelector('#enroll-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));players.push({...d,id:Math.max(...players.map(p=>p.id))+1,balance:50000,permit:false,modality:'Mensual',weight:30,height:135});modal.close();go('deportistas');toast('Ficha ficticia creada en esta prueba.');};}
function exportPlayers(){const rows=[['Nombre','Categoría','Modalidad','Habilitación'],...visiblePlayers().map(p=>[p.name,p.category,p.modality,eligible(p)?'Habilitado':'Restringido'])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(';')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='GHFC_deportistas_DEMO.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Lista de demostración exportada.');}
document.querySelector('#role').onchange=e=>{role=e.target.value;modal.close();go('inicio');};document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('.brand').onclick=e=>{e.preventDefault();go('inicio')};modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_club_demo_view',description:'Abre una pantalla del prototipo del club. No registra pagos ni cambia datos.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['inicio','deportistas','pagos','asistencia','sesiones','equipo','honorarios']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||!['inicio','deportistas','pagos','asistencia','sesiones','equipo','honorarios'].includes(input.view))throw new Error('Pantalla no válida');if(role==='coach'&&['pagos','equipo','honorarios'].includes(input.view))throw new Error('La vista de entrenador no incluye pagos');go(input.view);return {view,role,demo:true};}});}catch(e){console.warn('Herramienta de navegación no disponible');}}
